style:
:root{
  --ink:#1f1f1d; --ink-2:#4a4a46; --ink-3:#76756f;
  --rule:#dedbd2; --bg:#fdfcf9; --card:#f6f4ee; --accent:#534AB7;
}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{
  margin:0; padding:0 24px 96px;
  background:var(--bg); color:var(--ink);
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",
    "Hiragino Sans GB","Microsoft YaHei",system-ui,sans-serif;
  font-size:16.5px; line-height:1.85;
}
.wrap{max-width:860px;margin:0 auto}
h1{font-size:30px;line-height:1.35;font-weight:600;margin:56px 0 8px;letter-spacing:-.01em}
h2{font-size:23px;font-weight:600;margin:56px 0 14px;padding-top:22px;border-top:1px solid var(--rule)}
h3{font-size:18.5px;font-weight:600;margin:36px 0 10px}
h4{font-size:16.5px;font-weight:600;margin:26px 0 8px;color:var(--ink-2)}
p{margin:14px 0}
strong{font-weight:600}
a{color:var(--accent);text-decoration:none;border-bottom:1px solid rgba(83,74,183,.3)}
a:hover{border-bottom-color:var(--accent)}
blockquote{
  margin:22px 0;padding:14px 20px;background:var(--card);
  border-left:3px solid var(--accent);border-radius:0 6px 6px 0;color:var(--ink-2)
}
blockquote p{margin:6px 0}
ul,ol{padding-left:26px;margin:14px 0}
li{margin:6px 0}
code{
  font-family:ui-monospace,SFMono-Regular,"SF Mono",Menlo,Consolas,monospace;
  font-size:.88em;background:var(--card);padding:2px 6px;border-radius:4px
}
pre{
  background:var(--card);border:1px solid var(--rule);border-radius:8px;
  padding:16px 18px;overflow-x:auto;line-height:1.6;margin:20px 0
}
pre code{background:none;padding:0;font-size:13.5px}
table{
  border-collapse:collapse;width:100%;margin:22px 0;font-size:15px;
  display:block;overflow-x:auto
}
th,td{border:1px solid var(--rule);padding:9px 13px;text-align:left;vertical-align:top}
th{background:var(--card);font-weight:600;white-space:nowrap}
tbody tr:nth-child(even){background:rgba(246,244,238,.45)}
hr{border:none;border-top:1px solid var(--rule);margin:48px 0}
figure{margin:32px 0;text-align:center}
svg{
  max-width:100%;height:auto;display:block;margin:28px auto;
  background:#fff;border:1px solid var(--rule);border-radius:10px;padding:14px 8px
}
#TOC{
  background:var(--card);border:1px solid var(--rule);border-radius:10px;
  padding:20px 26px;margin:32px 0
}
#TOC ul{margin:6px 0;padding-left:22px}
#TOC>ul{padding-left:18px}
#TOC li{margin:3px 0}
#TOC a{border:none;color:var(--ink-2)}
#TOC a:hover{color:var(--accent)}
@media (max-width:640px){
  body{font-size:15.5px;padding:0 16px 64px}
  h1{font-size:25px}h2{font-size:20px}h3{font-size:17px}
  table{font-size:14px}
}
@media print{
  body{background:#fff;font-size:11pt;padding:0}
  h2{page-break-before:auto;break-inside:avoid}
  h2,h3,h4{break-after:avoid}
  svg,figure,table,pre,blockquote{break-inside:avoid}
  a{color:inherit;border:none}
  #TOC{break-after:page}
}
